 private string $openings;private string $cases;private string $acceptances;private string $occupancy;private string $turns;private string $readiness;
 public function __construct(string$root){$s=$root.'/var/imperium/offices/senate';$this->openings=$s.'/model-bound-profile-examination-testimony-openings';$this->cases=$s.'/profile-examination-cases';$this->acceptances=$s.'/model-bound-profile-examination-commission-acceptances';$this->occupancy=$s.'/occupancy';$this->turns=$s.'/model-bound-profile-evidence-testimony-turns';$this->readiness=$s.'/model-bound-profile-evidence-testimony-readiness';}
 public function examine(string$openingId,string$acceptanceId,string$senatorBindingId,\DateTimeImmutable$examinedAt):array
 {
  foreach(glob($this->turns.'/model-bound-profile-evidence-turn-*.json')?:[]as$p){$x=$this->read($p,'S267_MODEL_BOUND_EVIDENCE_TURN_CONFLICT');if(($x['source_acceptance']['id']??null)===$acceptanceId)return['turn'=>$x,'readiness'=>$this->ready($x['case_id'])];}
  $o=$this->read($this->openings.'/'.$openingId.'.json','S260_MODEL_BOUND_TESTIMONY_OPENING_ABSENT');$caseId=$o['case_id']??'';$case=$this->read($this->cases.'/'.$caseId.'.json','S261_MODEL_BOUND_EXAMINATION_CASE_ABSENT');$a=$this->read($this->acceptances.'/'.$acceptanceId.'.json','S262_MODEL_BOUND_ACCEPTANCE_ABSENT');$b=$this->read($this->occupancy.'/'.$senatorBindingId.'.json','S263_MODEL_BOUND_SENATOR_UNAVAILABLE');$seat=$b['seat']??'';$jurisdiction=str_starts_with($seat,'senate.committee.')?substr($seat,17):'';$authority=null;foreach($o['question_authorities']??[]as$x)if(($x['seat']??null)===$seat)$authority=$x;
  if(!$this->ok($o)||!$this->ok($case)||!$this->ok($a)||!$this->ok($b)||'imperium.senate-model-bound-profile-examination-testimony-opening/v1'!==($o['schema']??null)||'PROFILE_EXAMINATION_TESTIMONY_OPENED_PENDING_SENATOR_QUESTIONING'!==($o['status']??null)||true!==($o['testimony_open']??null)||true!==($o['senator_question_authority_exercisable']??null)||false!==($o['senator_finding_authority']??null)
   ||($o['case_digest']??null)!==($case['record_digest']??null)||($o['subject_profile']??null)!==($case['subject_profile']??null)||($o['evidence_chain']??null)!==($case['evidence_chain']??null)||($a['case_id']??null)!==$caseId||($a['case_digest']??null)!==$case['record_digest']||($a['senator']['binding_id']??null)!==$senatorBindingId||($a['senator']['binding_digest']??null)!==$b['record_digest']
   ||!in_array($jurisdiction,['trust','security','usability'],true)||!is_array($authority)||($authority['acceptance_id']??null)!==$acceptanceId||($authority['acceptance_digest']??null)!==$a['record_digest']||true!==($authority['senator_question_authority_exercisable']??null)||false!==($authority['senator_finding_authority']??null)||'ACTIVE'!==($b['status']??null)||true!==($b['binding_atomic']??null)||true!==($b['senator_question_authority']??null)||true===($b['execution_authority']??null))throw new \RuntimeException('S264_MODEL_BOUND_EVIDENCE_QUESTION_CHAIN_INVALID');
  $questions=['trust'=>'Does the sealed evidence establish trustworthy provenance, bounded behavior, and governed fallback handling?','security'=>'Does the sealed evidence preserve credential isolation, access restrictions, data boundaries, and safe configuration?','usability'=>'Does the sealed evidence establish task fitness, usable limits, and disclosed cost, latency, and fallback constraints?'];$citations=[];foreach(array_keys($case['evidence_chain'])as$key)$citations[]=['evidence_key'=>$key,'evidence_digest'=>'sha256:'.hash('sha256',CanonicalJson::encode($case['evidence_chain'][$key]))];$answer=['determination'=>'EVIDENCE_PRESENT_FOR_SENATOR_ASSESSMENT','citations'=>$citations,'access_status'=>$case['access_status'],'access_restrictions'=>$case['access_restrictions'],'model_configuration_digest'=>'sha256:'.hash('sha256',CanonicalJson::encode($case['model_binding'])),'limitations'=>['No live Manifestation was questioned.','No provider or assigned model was invoked.','Insufficient evidence must be attributed explicitly in the Senator finding.']];
