 }
 private function ready(string$caseId):?array{$turns=[];foreach(glob($this->turns.'/model-bound-profile-evidence-turn-*.json')?:[]as$p){$t=$this->read($p,'S267_MODEL_BOUND_EVIDENCE_TURN_CONFLICT');if(!$this->ok($t))throw new \RuntimeException('S267_MODEL_BOUND_EVIDENCE_TURN_CONFLICT');if(($t['case_id']??null)===$caseId)$turns[$t['jurisdiction']]=$t;}foreach(['trust','security','usability']as$j)if(!isset($turns[$j]))return null;$ordered=[];foreach(['trust','security','usability']as$j)$ordered[]=$turns[$j];$authorityId='model-bound-profile-finding-opening-authority-'.substr(hash('sha256',CanonicalJson::encode([$caseId,array_column($ordered,'record_digest')])),0,20);$id='model-bound-profile-evidence-readiness-'.substr(hash('sha256',CanonicalJson::encode([$caseId,$authorityId])),0,20);return$this->save($this->readiness,$id,['schema'=>'imperium.senate-model-bound-profile-evidence-testimony-readiness/v1','readiness_id'=>$id,'instance_id'=>$ordered[0]['instance_id'],'case_id'=>$caseId,'case_digest'=>$ordered[0]['case_digest'],'subject_profile'=>$ordered[0]['subject_profile'],'evidence_chain'=>$ordered[0]['evidence_chain'],'testimony_turns'=>array_map(static fn(array$t):array=>['jurisdiction'=>$t['jurisdiction'],'turn_id'=>$t['turn_id'],'turn_digest'=>$t['record_digest']],$ordered),'finding_authority_opening_authority'=>['authority_id'=>$authorityId,'authority_single_use'=>true,'lord_speaker_consumption_required'=>true,'status'=>'OPEN_PENDING_FINDING_AUTHORITY_OPENING'],'status'=>'PROFILE_EXAMINATION_TESTIMONY_ANSWERS_SEALED_PENDING_FINDING_AUTHORITY_OPENING','all_questions_dispatched_unchanged'=>true,'all_evidentiary_responses_sealed'=>true,'live_witness_questioned'=>false,'provider_invoked'=>false,'senator_finding_authority_exercisable'=>false,'deliberation_open'=>false,'profile_approval_authority'=>false,'profile_installation_authority'=>false,'profile_activation_authority'=>false,'deployment_authority'=>false,'execution_authority'=>false,'sealed'=>true]);}
 private function read(string$p,string$e):array{if(!is_file($p))throw new \RuntimeException($e);return json_decode((string)file_get_contents($p),true,512,JSON_THROW_ON_ERROR);}private function ok(array$r):bool{$d=$r['record_digest']??null;unset($r['record_digest']);return is_string($d)&&hash_equals($d,hash('sha256',CanonicalJson::encode($r)));}private function save(string$d,string$id,array$r):array{if(!is_dir($d)&&!mkdir($d,0770,true)&&!is_dir($d))throw new \RuntimeException('S266_MODEL_BOUND_EVIDENCE_TURN_FAILED');$r['record_digest']=hash('sha256',CanonicalJson::encode($r));$p=$d.'/'.$id.'.json';if(is_file($p)){if($this->read($p,'S267_MODEL_BOUND_EVIDENCE_TURN_CONFLICT')!==$r)throw new \RuntimeException('S267_MODEL_BOUND_EVIDENCE_TURN_CONFLICT');return$r;}file_put_contents($p,json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n",LOCK_EX);return$r;}
}
